function openEventEditor(id=null){if(!canPost())return;const e=id?state.events.find(x=>x.id===id):null;if(id&&!e?.mine)return;editor={kind:'event',id,photos:[]};editorDirty=false;showDialog(e?'Editar encontro':'Criar encontro',`<div class="form-grid">${field('event-title','Nome do encontro',e?.title||'','required minlength="5" maxlength="100" class="full"')}<label class="field-label">Data<input type="date" id="event-date" min="${dateISO()}" value="${e?.date||dateISO(1)}" required></label><label class="field-label">Horário<input type="time" id="event-time" value="${e?.time||'09:00'}" required></label>${field('event-place','Local',e?.place||'','required minlength="4" maxlength="160" class="full"')}${field('event-max','Número de vagas (opcional)',e?.max||'','type="number" min="1" max="10000" class="full"')}${field('event-desc','Sobre o encontro',e?.description||'','type="textarea" rows="3" required minlength="12" maxlength="2000" class="full"')}</div>`,`${btn('Cancelar','close-dialog','','text')}${btn(e?'Salvar alterações':'Publicar encontro','submit-event','','filled')}`,'editor');}
async function submitEvent(){if(!editor||!canPost()||!validFields(['event-title','event-place','event-max','event-desc']))return;const data={title:$('#event-title').value.trim(),date:$('#event-date').value,time:$('#event-time').value,place:$('#event-place').value.trim(),max:Number($('#event-max').value)||null,description:$('#event-desc').value.trim()};if(data.date<dateISO()||!data.time||data.title.length<5||data.description.length<12){notify('Confira a data, o horário e a descrição.','error');return;}const id=editor.id||uid('e'),old=state.events.find(e=>e.id===id);if(data.max&&old&&data.max<old.going){notify('O limite não pode ser menor que as presenças confirmadas.','error');return;}const ok=mutate(()=>{if(old)Object.assign(old,data);else state.events.unshift({...data,id,city:state.homeCity,mine:true,on:true,going:1,createdAt:Date.now()});},{redraw:false});if(ok){await closeDialog(true);navigate('evento',id);notify(old?'Encontro atualizado':'Encontro publicado');}}
